#include <stdexcept>
#include <sstream>
#include <charconv>
#include <memory>
#include <utility>

class Interval {
    int low_, high_;
public:
    Interval(int low, int high) : low_(low), high_(high) {
        if (low < -100 || high > 100 || low > high) throw std::invalid_argument("range");
    }
    int low() const { return low_; }
    int high() const { return high_; }
};

int main() {
    try{Interval r(3,3);
    std::cout<<r.low()<<" "<<r.high()<<"\n";
    }catch(const std::invalid_argument&){std::cout<<"range\n";
    }}

#include <iostream>
#include <string>
#include <vector>
#include <array>
#include <limits>
#include <stdexcept>
#include <sstream>
#include <charconv>
#include <memory>
#include <utility>

int nextTicket(int& counter) {
    if (counter < 0 || counter > 999) throw std::invalid_argument("range");
    // Save the old value, then update the caller-owned state.
    int issued = counter;
    ++counter;
    return issued;
}

int main() {
    int n;
    if(!(std::cin>>n))return 2;
    try{int issued=nextTicket(n);
    std::cout<<issued<<" "<<n<<"\n";
    }catch(const std::invalid_argument&){std::cout<<"range\n";
    }}

#include <iostream>
#include <string>
#include <vector>
#include <array>
#include <limits>
#include <stdexcept>
#include <sstream>
#include <charconv>
#include <memory>
#include <utility>

int* firstAbove(std::vector<int>& values, int threshold) {
    for (int& value : values) {
        if (value > threshold) return &value; // Borrow the actual element.
    }
    return nullptr;
}

int main() {
    std::vector<int> v{4,4,9};
    int* p=firstAbove(v,4);
    if(p)std::cout<<*p<<"\n";
    else std::cout<<"none\n";
    }

#include <iostream>
#include <string>
#include <vector>
#include <array>
#include <limits>
#include <stdexcept>
#include <sstream>
#include <charconv>
#include <memory>
#include <utility>

bool appendBounded(std::vector<int>& values, int value, std::size_t limit) {
    // Logical size is the number of live values, not capacity.
    if (value < -100 || value > 100 || values.size() >= limit) return false;
    values.push_back(value);
    return true;
}

int main() {
    std::vector<int> v{3,4};
    std::cout<<std::boolalpha<<appendBounded(v,5,2)<<" "<<v.size()<<"\n";
    }

#include <iostream>
#include <string>
#include <vector>
#include <array>
#include <limits>
#include <stdexcept>
#include <sstream>
#include <charconv>
#include <memory>
#include <utility>

struct Change { std::size_t index; int delta; };
bool applyBatch(std::vector<int>& stock, const std::vector<Change>& changes) {
    auto candidate = stock; // Original remains intact during validation.
    for (const auto& change : changes) {
        if (change.index >= candidate.size()) return false;
        int next = candidate[change.index] + change.delta;
        if (next < 0 || next > 1000) return false;
        candidate[change.index] = next;
    }
    stock.swap(candidate); // Commit the fully checked batch.
    return true;
}

int main() {
    std::vector<int> v{5,2};
    bool ok=applyBatch(v,{{0,-1},{1,-3}});
    std::cout<<std::boolalpha<<ok<<" "<<v[0]<<" "<<v[1]<<"\n";
    }

#include <iostream>
#include <string>
#include <vector>
#include <array>
#include <limits>
#include <stdexcept>
#include <sstream>
#include <charconv>
#include <memory>
#include <utility>

class Stock {
    int count_;
public:
    explicit Stock(int count) : count_(count) {
        if (count < 0 || count > 100) throw std::invalid_argument("range");
    }
    int count() const { return count_; }
    bool take(int amount) {
        if (amount < 0 || amount > count_) return false;
        count_ -= amount; // Private state changes only after validation.
        return true;
    }
};

int main() {
    Stock s(5);
    bool ok=s.take(5);
    std::cout<<std::boolalpha<<ok<<" "<<s.count()<<"\n";
    }

#include <iostream>
#include <string>
#include <vector>
#include <array>
#include <limits>
#include <stdexcept>
#include <sstream>
#include <charconv>
#include <memory>
#include <utility>

enum class ParcelState { pending, ready };
struct Parcel { int weight; ParcelState state; };
bool releaseParcel(Parcel& parcel) {
    if (parcel.state != ParcelState::pending || parcel.weight < 1 || parcel.weight > 100) return false;
    parcel.state = ParcelState::ready; // Commit the permitted transition.
    return true;
}

int main() {
    Parcel p{0,ParcelState::pending};
    bool ok=releaseParcel(p);
    std::cout<<std::boolalpha<<ok<<" "<<(p.state==ParcelState::pending)<<"\n";
    }

#include <iostream>
#include <string>
#include <vector>
#include <array>
#include <limits>
#include <stdexcept>
#include <sstream>
#include <charconv>
#include <memory>
#include <utility>

bool shiftAll(std::vector<int>& values, int delta) {
    // Validate the entire batch before the first write.
    for (int value : values) if (value + delta < -100 || value + delta > 100) return false;
    for (int& value : values) value += delta;
    return true;
}

int main() {
    std::vector<int> v{1,99};
    bool ok=shiftAll(v,2);
    std::cout<<std::boolalpha<<ok<<" "<<v[0]<<" "<<v[1]<<"\n";
    }

#include <iostream>
#include <string>
#include <vector>
#include <array>
#include <limits>
#include <stdexcept>
#include <sstream>
#include <charconv>
#include <memory>
#include <utility>

int priceTotal(int unit, int count) {
    // A long intermediate holds this bounded product.
    // Check the int range before narrowing the return value.
    if (unit < 0 || unit > 1000 || count < 0 || count > 100) throw std::invalid_argument("range");
    long result = static_cast<long>(unit) * count;
    if (result > std::numeric_limits<int>::max()) throw std::out_of_range("overflow");
    return static_cast<int>(result);
}

int main() {
    int u,n;
    if(!(std::cin>>u>>n))return 2;
    try{std::cout<<priceTotal(u,n)<<"\n";
    }catch(const std::exception& e){std::cout<<e.what()<<"\n";
    }}

